sp_widget.css:
.task-overview {
    display: flex;
    gap: 20px;
}

.task-card {
    flex: 1;
    padding: 20px;
    border-radius: 8px;
    color: white;
    text-align: center;
    font-size: 18px;
    font-weight: bold;
}

.task-card.pending { background: #ff9800; } /* Orange */
.task-card.in-progress { background: #2196f3; } /* Blue */
.task-card.completed { background: #4caf50; } /* Green */

sp_widget.script:
(function() {
    var result = {
        pending: 0,
        in_progress: 0,
        completed: 0
    };

    var gr = new GlideAggregate('x_1583423_hr_hroo_onboarding_task'); // Replace with your Task table name
    gr.addAggregate('COUNT');
    gr.addQuery('state', '!=', 'closed'); // Fetch only active tasks
    gr.groupBy('state');
    gr.query();

    while (gr.next()) {
        var state = gr.getValue('state');
        var count = gr.getAggregate('COUNT');

        if (state == 'pending') result.pending = count;
        else if (state == 'in_progress') result.in_progress = count;
        else if (state == 'completed') result.completed = count;
    }

    data.taskSummary = result;
})();
